def asignar_profesional(apps, schema_editor):
    """
    Los cobros de antes no decían quién atendió. Se les pone el de la
    última cita atendida del paciente hasta ese día (o, si no hubo, la más
    cercana): es lo más probable, y la clínica lo corrige desde Finanzas.
    """
    Payment = apps.get_model("billing", "Payment")
    Appointment = apps.get_model("agenda", "Appointment")
    for pago in Payment.objects.filter(profesional__isnull=True).iterator():
        citas = Appointment.objects.filter(patient_id=pago.patient_id).select_related("doctor")
        cita = (citas.filter(status="completed", scheduled_start__date__lte=pago.date)
                .order_by("-scheduled_start").first()
                or citas.order_by("-scheduled_start").first())
        if cita is not None and cita.doctor_id:
            pago.profesional_id = cita.doctor.user_id
            pago.save(update_fields=["profesional"])


